mapper.sql:
AND s.user_id = #{userId}

    AND COALESCE(r.generated_at, r.updated_at)
        >= DATE_SUB(UTC_TIMESTAMP(6), INTERVAL #{days} DAY)

AND s.topic_mode = #{topicMode}
AND s.form = #{form}
AND r.hiring_recommendation = #{recommendation}
AND s.interviewer_id = #{interviewerId}

mapper.select:
SELECT FROM interview_report r JOIN interview_session s ON s.id = r.session_id WHERE s.user_id = #{userId} AND r.status = 'REPORT_READY' AND r.scoring_rule_version = #{ruleVersion}
AND r.generated_at >= DATE_SUB(UTC_TIMESTAMP(6), INTERVAL #{days} DAY)
ORDER BY r.generated_at ASC, r.id ASC LIMIT 500
